body=box(140,110,170,280,'Líquido')+line(140,175,310,175)+line(310,330,550,330)+text(340,305,'Tomada A: 2 m abaixo da superfície',20)+text(50,450,'ρ=1.000 kg/m³; g=10 m/s²; superfície a 100 kPa absolutos',20)+text(50,490,'Modelo estático: P=Psuperfície+ρgh',20)
