schema('incendio','caminhos_termicos_paralelos','Modelo térmico de dois caminhos paralelos','Entre superfícies quentes e frias deltaT12K, caminhosR1=2K/W eR2=6K/W em paralelo; potência deltaT/R.',body,'Qual potência térmica total e qual fração passa pelo caminho de menor resistência?', ['8 W; 75%.','2 W; 25%.','1,5 W; 50%.','8 W; 25%.','6 W; 100%.'],'Potências6W e2W, total8W. O caminhoR1 menor leva6/8=75%. Resistências em paralelo não se somam como se fossem série.','heatParallel',[12,2,6],[8,.75])
