schema('higiene_ocupacional','residencia_duas_etapas','Modelo de lavagem em duas etapas','TanquesA eB em série, cada10L e vazão2L/min, mistura perfeita; tempo médioV/q e tempos médios somam.',body,'Qual tempo médio de residência no conjunto e qual limitação da conclusão?', ['10 min; não significa que toda partícula saia exatamente nesse tempo.','5 min; um dos tanques não participa do percurso.','20 min; multiplica-se a soma dos volumes pela vazão.','10 min; todas as partículas têm necessariamente tempo idêntico.','2 min; a vazão define diretamente o tempo.'],'Cada etapa tem média5min e o conjunto10min. Mistura perfeita produz distribuição de tempos; média não é trajeto temporal determinístico de toda partícula.','residence',[10,10,2],10)
body=diagram({'a':(45,160,'Ameaça'), 'c':(355,160,'Evento central'), 'd':(700,160,'Dano'), 'e':(355,330,'Fator E')},[('a','c','B1'),('c','d','B2'),('e','c','degrada B1')],['B1 evita perda de contenção; B2 limita o dano após a perda.','Fator E reduz a eficácia de B1; controle C atua sobre E.'])
schema('gerenciamento_riscos','barreira_e_controle_da_degradacao','Barreiras e fator de degradação','Ameaça→B1→evento central→B2→dano. E degradaB1; controleC age sobreE. B1 previne perda; B2 limita dano após perda.',body,'Sem assumir independência probabilística, qual crédito adicional não está demonstrado pelo diagrama?', ['Contar C como segunda prevenção independente de B1 sem analisar sua dependência funcional.','Tratar B2 como mitigação posterior ao evento central.','Identificar E como fator que afeta a prevenção.','Examinar a eficácia de C no controle de E.','Reconhecer B1 como controle anterior à perda.'],'C protege a disponibilidade deB1 por agir sobreE; isso não o torna automaticamente outra prevenção independente do mesmo evento. O diagrama não fornece probabilidades.','barrierRole',{'C':'E','E':'B1'},'dependencia')
