def person(x,y):
 return f'<circle cx="{x}" cy="{y}" r="17" fill="#e7ae77"/>'+line(x,y+17,x,y+80,'#243c56',12)+line(x,y+40,x-28,y+65,'#243c56',8)+line(x,y+40,x+28,y+65,'#243c56',8)+line(x,y+80,x-25,y+125,'#243c56',9)+line(x,y+80,x+25,y+125,'#243c56',9)
def scene(topic,sub,title,alt,body,statement,choices,exp,op,inputs,result):
 add(topic,sub,statement,choices,exp,kind='ilustracao',visual=(title,alt,body,dict(operation=op,inputs=inputs,result=result)))
